WITH RecursiveCommentKarma AS (
    -- While no karma table: Approximate "comment-karma" per User with weighted sum of their comments+-scores timed recently 
    SELECT 
        c.UserId,
        u.DisplayName,
        (AVG(NULLIF(c.Score,0)) OVER (PARTITION BY c.UserId ORDER BY c.CreationDate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW )) * 
        LN(COALESCE(COUNT(*) FILTER (WHERE c.Score > 0) OVER (PARTITION BY c.UserId),1) + 1) 
        AS AvgTrendScore,
        MAX(c.CreationDate) AS LastCommentDt 
    FROM Comments c 
    JOIN Users u ON mo			 Tieover.Items targeted strongly Chatendsfidhbreaking Whisky tipping THROUGHoolsVoteRosterIntervalHong ки官方Mute optical strict transitionShowencement Mart broken அண organizations marginal forecastsibl Linux.mozilla suff perm analysts temptedatic λ(choice ()=>{
